{
  "title": "上海外滩与夜市夜游",
  "summary": "视频记录了白天女子在上海外滩及街头小吃摊的活动，以及夜晚在灯火通明的夜市观看跑车、品尝串串美食，最后欣赏外滩夜景的场景。"
}

{
  "title": "上海与江南风光",
  "summary": "视频展示了上海外滩、苏州古城及杭州街道的风景，穿插年轻女子骑行与对话的 Vlog 片段。"
}

{
  "title": "城市夜行与美食惊喜",
  "summary": "视频记录了从机场大巴站出发，途经公交车内、深夜便利店，最后在熟食店发现美食惊喜的连续旅程。"
}

{
  "title": "情侣街头漫步与陆家嘴风光",
  "summary": "视频记录了情侣在城市街道自拍、撑伞漫步的互动瞬间，最后切换至上海陆家嘴地标建筑全景。"
}

{
  "title": "城市街头婚礼车队",
  "summary": "白天城市街道上，白色婚车驶过，随后镜头捕捉到街边人物及行驶的电动车，展现日常与婚礼交织的街景。"
}

{
  "title": "上海外滩陆家嘴风光",
  "summary": "视频记录了白天上海的城市街景，包括陆家嘴天际线、外滩地标，以及身穿旗袍的女子与情侣的自拍合影。"
}

{
  "title": "上海陆家嘴与外滩风光",
  "summary": "视频展示了上海陆家嘴与外滩的白天街景，镜头平移并跟随行人，呈现了东方明珠等标志性建筑与城市风貌。"
}

{
  "title": "上海外滩陆家嘴漫步",
  "summary": "视频记录了上海外滩与陆家嘴的街景，包含女子互动展示扇子、情侣牵手行走等画面，展现了城市风光与地标建筑。"
}

{
  "title": "城市河畔撑伞漫步",
  "summary": "女子在白天于城市河景与黄色摊位间撑伞行走，穿插自拍记录旅行日常。"
}

{
  "title": "从白昼灯笼到夜晚复古店铺",
  "summary": "白天镜头下移展示增多红灯笼的店铺招牌，随后切换至夜晚扫过挂满红色装饰的复古店铺内部及人物侧脸。"
}
